import { useEffect, useState, type FormEvent, type ReactNode } from 'react'
import { ArrowDown, ArrowRight, ArrowUpRight, Bell, Bot, Check, ChevronDown, ChevronRight, CircleHelp, CreditCard, FileCheck2, FileText, GraduationCap, LayoutDashboard, LockKeyhole, Menu, MessageCircle, Search, Send, Settings2, ShieldCheck, Sparkles, UploadCloud, X } from 'lucide-react'

type Page = 'Overview' | 'My application' | 'Documents' | 'Scholarship' | 'Fees & payment' | 'Help & support'
type AuthMode = 'student-login' | 'register' | 'otp' | 'forgot' | 'staff-login'
const pages: { name: Page; icon: typeof LayoutDashboard }[] = [
  { name: 'Overview', icon: LayoutDashboard }, { name: 'My application', icon: FileText }, { name: 'Documents', icon: FileCheck2 }, { name: 'Scholarship', icon: GraduationCap }, { name: 'Fees & payment', icon: CreditCard }, { name: 'Help & support', icon: CircleHelp },
]

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000/api'

async function apiPost<T=Record<string,unknown>>(path:string,body:Record<string,unknown>):Promise<T>{
  const csrfResponse=await fetch(`${API_BASE_URL}/csrf/`,{credentials:'include'})
  if(!csrfResponse.ok)throw new Error('Cannot reach the SVPM backend. Start Django at http://localhost:8000.')
  const csrf=document.cookie.split('; ').find(row=>row.startsWith('csrftoken='))?.split('=').slice(1).join('=')
  const response=await fetch(`${API_BASE_URL}${path}`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRFToken':decodeURIComponent(csrf)}:{})},body:JSON.stringify(body)})
  const data=await response.json().catch(()=>({detail:'The backend returned an unreadable response.'})) as Record<string,unknown>
  if(!response.ok){const detail=data.detail??Object.entries(data).map(([key,value])=>`${key}: ${Array.isArray(value)?value.join(' '):String(value)}`).join(' ');throw new Error(typeof detail==='string'?detail:'Request failed. Please try again.')}
  return data as T
}

async function apiUpload<T=Record<string,unknown>>(path:string,body:FormData):Promise<T>{
  const csrfResponse=await fetch(`${API_BASE_URL}/csrf/`,{credentials:'include'})
  if(!csrfResponse.ok)throw new Error('Cannot reach the SVPM backend. Start Django at http://localhost:8000.')
  const csrf=document.cookie.split('; ').find(row=>row.startsWith('csrftoken='))?.split('=').slice(1).join('=')
  const response=await fetch(`${API_BASE_URL}${path}`,{method:'POST',credentials:'include',headers:csrf?{'X-CSRFToken':decodeURIComponent(csrf)}:{},body})
  const data=await response.json().catch(()=>({detail:'The backend returned an unreadable response.'})) as Record<string,unknown>
  if(!response.ok){const detail=data.detail??Object.entries(data).map(([key,value])=>`${key}: ${Array.isArray(value)?value.join(' '):String(value)}`).join(' ');throw new Error(typeof detail==='string'?detail:'Upload failed. Please try again.')}
  return data as T
}

async function apiPatch<T=Record<string,unknown>>(path:string,body:Record<string,unknown>):Promise<T>{
  const csrfResponse=await fetch(`${API_BASE_URL}/csrf/`,{credentials:'include'})
  if(!csrfResponse.ok)throw new Error('Cannot reach the SVPM backend. Start Django at http://localhost:8000.')
  const csrf=document.cookie.split('; ').find(row=>row.startsWith('csrftoken='))?.split('=').slice(1).join('=')
  const response=await fetch(`${API_BASE_URL}${path}`,{method:'PATCH',credentials:'include',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRFToken':decodeURIComponent(csrf)}:{})},body:JSON.stringify(body)})
  const data=await response.json().catch(()=>({detail:'The backend returned an unreadable response.'})) as Record<string,unknown>
  if(!response.ok){const detail=data.detail??Object.entries(data).map(([key,value])=>`${key}: ${Array.isArray(value)?value.join(' '):String(value)}`).join(' ');throw new Error(typeof detail==='string'?detail:'Update failed. Please try again.')}
  return data as T
}

function App() {
  const [page, setPage] = useState<Page>('Overview')
  const [auth, setAuth] = useState<AuthMode>('student-login')
  const [signedIn, setSignedIn] = useState(false)
  const [staff, setStaff] = useState(false)
  const [menu, setMenu] = useState(false)
  const [chat, setChat] = useState(false)
  const [message, setMessage] = useState('')
  const [sent, setSent] = useState<string[]>([])
  const [toast, setToast] = useState('')
  useEffect(() => { fetch(`${API_BASE_URL}/me/`, { credentials: 'include' }).then(async response => response.ok ? response.json() : null).then((user: {is_staff:boolean}|null) => { if (user) { setStaff(user.is_staff); setSignedIn(true) } }).catch(() => {}) }, [])
  const notify = (s: string) => { setToast(s); window.setTimeout(() => setToast(''), 3000) }
  const signIn = (asStaff: boolean) => { setStaff(asStaff); setSignedIn(true); setPage('Overview') }
  if (!signedIn) return <AuthScreen mode={auth} setMode={setAuth} signIn={signIn} />

  return <div className="shell">
    <aside className={`sidebar ${menu ? 'show' : ''}`}>
      <div className="brand"><img src="/images/svpm-logo.png" alt="SVPM logo"/><div><strong>SVPM</strong><span>ADMISSIONS PORTAL</span></div><button className="mobile-close" onClick={()=>setMenu(false)} aria-label="Close menu"><X size={18}/></button></div>
      <div className="portal-label">PORTAL MENU</div>
      <nav>{staff&&<button className="nav-item staff-doc-nav" onClick={()=>{document.getElementById('staff-student-documents')?.scrollIntoView({behavior:'smooth',block:'start'});setMenu(false)}}><FileCheck2 size={18}/><span>Student document uploads</span></button>}{pages.map(({name,icon:Icon})=><button key={name} className={`nav-item ${name===page&&!staff?'active':''}`} onClick={()=>{setPage(name);setMenu(false)}}><Icon size={18}/><span>{name}</span>{name==='Documents'&&<i className="nav-dot"/>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><MessageCircle size={17}/></div><strong>Need a hand?</strong><p>Our admissions team is here to help.</p><button onClick={()=>setChat(true)}>Chat with us <ArrowRight size={14}/></button></div><button className="nav-item settings" onClick={()=>notify('Settings are coming soon')}><Settings2 size={18}/><span>Settings</span></button></div>
      <div className="sidebar-footer"><span className="live-dot"/> Admissions 2026–27 <span className="version">v1.0</span></div>
    </aside>
    <main className="main-area">
      <header className="topbar"><button className="menu-button" onClick={()=>setMenu(true)} aria-label="Open menu"><Menu size={20}/></button><div className="crumb">{staff?'Staff workspace':'Student portal'} <ChevronRight size={14}/><b>{staff?'Admissions overview':page}</b></div><div className="top-actions">{staff&&<span className="staff-role-badge"><ShieldCheck size={14}/> Staff workspace</span>}<button className="icon-button notification" onClick={()=>notify('You’re all caught up')} aria-label="Notifications"><Bell size={18}/></button><span className="top-divider"/><button className="profile" onClick={async()=>{try{await apiPost('/auth/logout/',{})}catch{}setSignedIn(false);setAuth(staff?'staff-login':'student-login')}} title="Sign out"><span className="avatar">{staff?'ST':'AS'}</span><span className="profile-copy"><b>{staff?'Staff member':'Student account'}</b><small>{staff?'Authorized staff account':'Applicant · 2026–27'}</small></span><ChevronDown size={14}/></button></div></header>
      <div className="content">{staff?<StaffDashboard notify={notify}/>:page==='Overview'?<StudentOverview go={setPage}/>:<SectionPage page={page} notify={notify}/>}</div>
    </main>
    <button className="chat-launcher" onClick={()=>setChat(!chat)} aria-label="Open admissions assistant">{chat?<X size={22}/>:<><Bot size={22}/><span className="chat-ping"/></>}</button>
    {chat&&<section className="chat-panel"><div className="chat-head"><div className="bot-avatar"><Sparkles size={18}/></div><div><b>SVPM Assistant</b><span><i/> Online · Here to help</span></div><button onClick={()=>setChat(false)} aria-label="Close chat"><X size={18}/></button></div><div className="chat-body"><div className="chat-date">TODAY</div><div className="chat-bubble bot-bubble">Hi! I’m your SVPM admissions assistant. What can I help you with?<small>Just now</small></div><div className="quick-questions">{['Required documents','Application status','Scholarships'].map(q=><button key={q} onClick={()=>setSent([...sent,q])}>{q}</button>)}</div>{sent.map((s,i)=><div className="chat-bubble user-bubble" key={i}>{s}<small>Just now</small></div>)}</div><form className="chat-input" onSubmit={e=>{e.preventDefault();if(message.trim())setSent([...sent,message.trim()]);setMessage('')}}><input value={message} onChange={e=>setMessage(e.target.value)} placeholder="Ask me anything…"/><button aria-label="Send"><Send size={17}/></button></form><div className="chat-powered">SVPM Admissions Assistant</div></section>}
    {toast&&<div className="toast"><Check size={16}/>{toast}</div>}
  </div>
}

function AuthScreen({mode,setMode,signIn}:{mode:AuthMode;setMode:(mode:AuthMode)=>void;signIn:(staff:boolean)=>void}) {
  const [busy,setBusy]=useState(false)
  const [error,setError]=useState('')
  const [notice,setNotice]=useState('')
  const [challengeId,setChallengeId]=useState('')
  const [resetChallengeId,setResetChallengeId]=useState('')
  const [resetSent,setResetSent]=useState(false)
  const [year,setYear]=useState('')
  const [showPassword,setShowPassword]=useState(false)
  const isRegister=mode==='register',isOtp=mode==='otp',isForgot=mode==='forgot',isStaff=mode==='staff-login'
  const title=isRegister?'Create your applicant account':isOtp?'Verify your contact details':isForgot?'Reset your password':isStaff?'Staff sign in':'Welcome to SVPM'
  const doSubmit=async(e:FormEvent<HTMLFormElement>,action:(data:FormData)=>Promise<void>)=>{e.preventDefault();setError('');setNotice('');setBusy(true);try{await action(new FormData(e.currentTarget))}catch(err){setError(err instanceof Error?err.message:'Something went wrong. Please try again.')}finally{setBusy(false)}}
  const onLogin=(e:FormEvent<HTMLFormElement>)=>doSubmit(e,async data=>{
    const result=await apiPost<{is_staff:boolean}>('/auth/login/',{username:String(data.get('username')||''),password:String(data.get('password')||'')})
    if(isStaff&&!result.is_staff)throw new Error('This account is not authorized for staff access.')
    if(!isStaff&&result.is_staff)throw new Error('Please use the staff sign-in option for this account.')
    signIn(result.is_staff)
  })
  const onRegister=(e:FormEvent<HTMLFormElement>)=>doSubmit(e,async data=>{
    const password=String(data.get('password')||'')
    if(password!==String(data.get('confirm_password')||''))throw new Error('The passwords do not match.')
    const result=await apiPost<{challenge_id:string;delivery_mode:string}>('/auth/register/start/',{full_name:String(data.get('full_name')||''),prn:String(data.get('prn')||''),email:String(data.get('email')||''),mobile:String(data.get('mobile')||''),entry_year:Number(year),password})
    setChallengeId(result.challenge_id);setNotice(result.delivery_mode==='development-console'?'Verification codes were generated. In development, check the Django terminal for the email and SMS codes.':'Verification codes were sent to the registered email and mobile.');setMode('otp')
  })
  const onVerify=(e:FormEvent<HTMLFormElement>)=>doSubmit(e,async data=>{
    const result=await apiPost<{is_staff:boolean}>('/auth/register/verify/',{challenge_id:challengeId,email_code:String(data.get('email_code')||''),mobile_code:String(data.get('mobile_code')||'')})
    setNotice('Account created and verified.');signIn(result.is_staff)
  })
  const onResetStart=(e:FormEvent<HTMLFormElement>)=>doSubmit(e,async data=>{
    const result=await apiPost<{challenge_id:string;delivery_mode:string}>('/auth/password-reset/start/',{identifier:String(data.get('identifier')||'')})
    setResetChallengeId(result.challenge_id);setResetSent(true);setNotice(result.delivery_mode==='development-console'?'If the account exists, its verification codes are printed in the Django terminal.':'If the account exists, codes were sent to its registered email and mobile.')
  })
  const onResetComplete=(e:FormEvent<HTMLFormElement>)=>doSubmit(e,async data=>{
    const password=String(data.get('new_password')||'')
    if(password!==String(data.get('confirm_password')||''))throw new Error('The passwords do not match.')
    await apiPost('/auth/password-reset/complete/',{challenge_id:resetChallengeId,email_code:String(data.get('email_code')||''),mobile_code:String(data.get('mobile_code')||''),new_password:password})
    setNotice('Password changed. Sign in using your new password.');setMode('student-login');setResetSent(false);setResetChallengeId('')
  })
  const busyButton=(text:string)=><button className="auth-submit" disabled={busy}>{busy?'Please wait…':text} <ArrowRight size={16}/></button>
  return <div className="auth-screen"><div className="auth-photo"/><div className="auth-panel"><div className="auth-brand"><img src="/images/svpm-logo.png" alt="SVPM logo"/><div><b>SVPM</b><span>COLLEGE OF ENGINEERING</span></div></div><div className="auth-body"><div className="eyebrow green">ADMISSIONS PORTAL · 2026–27</div><h1>{title}</h1><p className="auth-lede">{isRegister?'For continuing students applying for 2nd, 3rd, or 4th year admission.':isOtp?'We’ll verify both your email address and mobile number before creating your account.':isForgot?'Verify your registered email and mobile to reset your password.':isStaff?'Use the unique staff ID and password provided by SVPM.':'Sign in to continue your admission journey.'}</p>
    {error&&<div className="auth-notice" role="alert">{error}</div>}{notice&&<div className="auth-notice" role="status">{notice}</div>}
    {isOtp?<form className="auth-form" onSubmit={onVerify}><div className="otp-note"><ShieldCheck size={18}/><span>Enter both six-digit verification codes<small>Each code expires after five minutes.</small></span></div><label>Email verification code<input name="email_code" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} placeholder="6-digit email code" autoComplete="one-time-code"/></label><label>Mobile verification code<input name="mobile_code" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} placeholder="6-digit SMS code" autoComplete="one-time-code"/></label>{busyButton('Verify & create account')}<button type="button" className="auth-text-button" onClick={()=>{setError('');setMode('register')}}>Back to registration</button></form>:isRegister?<form className="auth-form" onSubmit={onRegister}><div className="auth-two"><label>Full name<input name="full_name" required autoComplete="name" placeholder="As shown on college records"/></label><label>PRN number<input name="prn" required placeholder="Your college PRN"/></label></div><div className="auth-two"><label>Email address<input name="email" required type="email" autoComplete="email" placeholder="you@example.com"/></label><label>Mobile number<input name="mobile" required type="tel" autoComplete="tel" placeholder="10-digit mobile number"/></label></div><label>Applying for year<select value={year} onChange={e=>setYear(e.target.value)} required><option value="" disabled>Select admission year</option><option value="2">2nd year</option><option value="3">3rd year</option><option value="4">4th year</option></select></label><div className="auth-two"><label>Create password<input name="password" required minLength={8} autoComplete="new-password" type={showPassword?'text':'password'} placeholder="At least 8 characters"/></label><label>Confirm password<input name="confirm_password" required minLength={8} autoComplete="new-password" type={showPassword?'text':'password'} placeholder="Re-enter password"/></label></div><label className="check-label"><input type="checkbox" onChange={e=>setShowPassword(e.target.checked)}/> Show passwords</label><p className="auth-small-note">Registration requires your PRN, name, email, and mobile to match a record uploaded by college staff.</p>{busyButton('Continue to verification')}<button type="button" className="auth-text-button" onClick={()=>setMode('student-login')}>Already registered? Sign in</button></form>:isForgot?<>{!resetSent?<form className="auth-form" onSubmit={onResetStart}><label>PRN, registered email, or mobile<input name="identifier" required autoComplete="username" placeholder="Enter your account details"/></label>{busyButton('Send verification codes')}<button type="button" className="auth-text-button" onClick={()=>setMode('student-login')}>Back to sign in</button></form>:<form className="auth-form" onSubmit={onResetComplete}><label>Email verification code<input name="email_code" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code"/></label><label>Mobile verification code<input name="mobile_code" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code"/></label><div className="auth-two"><label>New password<input name="new_password" required type={showPassword?'text':'password'} minLength={8} autoComplete="new-password"/></label><label>Confirm password<input name="confirm_password" required type={showPassword?'text':'password'} minLength={8} autoComplete="new-password"/></label></div><label className="check-label"><input type="checkbox" onChange={e=>setShowPassword(e.target.checked)}/> Show passwords</label>{busyButton('Reset password')}<button type="button" className="auth-text-button" onClick={()=>{setResetSent(false);setResetChallengeId('');setNotice('')}}>Use a different account</button></form>}</>:<form className="auth-form" onSubmit={onLogin}><label>{isStaff?'Unique staff ID':'PRN / username'}<input name="username" required autoComplete="username" placeholder={isStaff?'Enter your staff ID':'Enter your PRN or username'}/></label><label>Password<input name="password" required type={showPassword?'text':'password'} autoComplete="current-password" placeholder="Enter your password"/></label><label className="check-label"><input type="checkbox" onChange={e=>setShowPassword(e.target.checked)}/> Show password</label>{!isStaff&&<button type="button" className="forgot-link" onClick={()=>{setResetSent(false);setNotice('');setMode('forgot')}}>Forgot password?</button>}{busyButton(isStaff?'Sign in to staff workspace':'Sign in')}{!isStaff&&<div className="auth-register-prompt">New to SVPM admissions? <button type="button" onClick={()=>{setNotice('');setMode('register')}}>Create an account</button></div>}<div className="auth-separator"><span>OR</span></div><button type="button" className="staff-login-button" onClick={()=>setMode(isStaff?'student-login':'staff-login')}>{isStaff?'Student sign in':'Sign in as staff'} <ArrowRight size={15}/></button></form>}
  </div><footer className="auth-footer"><span>© 2026 SVPM College of Engineering</span><span><LockKeyhole size={13}/> Secure admissions portal</span></footer></div><div className="auth-photo-caption"><span className="live-dot"/> SVPM COLLEGE OF ENGINEERING <span>·</span> Admissions 2026–27</div></div>
}
function StudentOverview({go}:{go:(page:Page)=>void}) {return <><section className="welcome"><div className="welcome-bg"/><div className="welcome-content"><span className="eyebrow"><span className="live-dot"/> ADMISSIONS 2026–27</span><h1>Your future starts<br/>right here, Aditi.</h1><p>One step at a time. Your SVPM journey is taking shape.</p><button className="hero-button" onClick={()=>go('My application')}>Continue application <ArrowRight size={16}/></button></div><div className="welcome-mark"><img src="/images/svpm-logo.png" alt="SVPM College of Engineering"/></div><div className="welcome-bottom"><span><ShieldCheck size={15}/> Your information is secure</span><span>SVPM College of Engineering <ArrowUpRight size={14}/></span></div></section>
  <div className="section-heading"><div><div className="eyebrow green">YOUR ADMISSIONS JOURNEY</div><h2>Application overview</h2></div><button className="text-link" onClick={()=>go('My application')}>View full application <ArrowRight size={15}/></button></div>
  <div className="stats-grid"><article className="stat-card"><div className="stat-top"><span>Application progress</span><span className="soft-icon"><LayoutDashboard size={17}/></span></div><div className="stat-value">72<span>%</span></div><div className="progress-track"><span style={{width:'72%'}}/></div><small>Looking good — keep it going</small></article><article className="stat-card"><div className="stat-top"><span>Documents verified</span><span className="soft-icon"><FileCheck2 size={17}/></span></div><div className="stat-value">4<span className="stat-slash"> / 5</span></div><div className="stat-foot">1 document needs attention</div></article><article className="stat-card"><div className="stat-top"><span>Scholarship status</span><span className="soft-icon"><GraduationCap size={17}/></span></div><div className="stat-pill pending">Under review</div><div className="stat-foot">Updated 24 September, 2026</div></article><article className="stat-card"><div className="stat-top"><span>Fees paid</span><span className="soft-icon"><CreditCard size={17}/></span></div><div className="stat-value rupee">₹25,000</div><div className="stat-foot">of ₹85,000 total fees</div></article></div>
  <div className="dashboard-columns"><section className="panel journey-panel"><div className="panel-heading"><div><h3>Your application journey</h3><p>Here’s where you are in the process</p></div></div><div className="journey-list"><JourneyStep done title="Account created" date="Complete"/><JourneyStep done title="Admission form submitted" date="Complete"/><JourneyStep current title="PRN and document verification" date="Staff review in progress"/><JourneyStep title="Scholarship review" date="If applicable"/><JourneyStep title="Fee payment & admission" date="Next step" last/></div><button className="journey-link" onClick={()=>go('My application')}>Complete application form <ArrowRight size={15}/></button></section><div className="right-stack"><section className="panel doc-panel"><div className="panel-heading"><div><h3>Documents</h3><p>Staff verifies uploaded records</p></div><button className="text-link small-link" onClick={()=>go('Documents')}>View all</button></div><div className="doc-row"><span className="file-icon pdf">PDF</span><div className="doc-copy"><b>PRN proof</b><small>Required for every student</small></div><span className="verified-tag"><Check size={13}/> Required</span></div><button className="attention-row" onClick={()=>go('Documents')}><span className="doc-copy"><b>Open document checklist</b><small>See current review status</small></span><ChevronRight size={16}/></button></section><section className="panel payment-panel"><div className="panel-heading"><div><h3>Fee payment</h3><p>View balance and receipts</p></div><span className="paid-check"><Check size={16}/></span></div><div className="fee-amount"><span>₹25,000</span><small>sample payment data</small></div><div className="fee-bottom"><span>Balance shown in fee page</span><button onClick={()=>go('Fees & payment')}>View fees <ArrowRight size={13}/></button></div></section></div></div><section className="bottom-banner"><div className="banner-icon"><Sparkles size={18}/></div><div><b>Need help with your form?</b><p>Ask the admissions assistant about PRN, documents, scholarships, or fees.</p></div><button onClick={()=>document.querySelector<HTMLButtonElement>('.chat-launcher')?.click()}>Ask a question <ArrowRight size={15}/></button></section><footer className="page-footer"><span>© 2026 SVPM College of Engineering</span><span>Admissions 2026–27</span></footer></>}

function JourneyStep({done=false,current=false,title,date,last=false}:{done?:boolean;current?:boolean;title:string;date:string;last?:boolean}){return <div className={`journey-step ${done?'done':''} ${current?'current':''} ${last?'last':''}`}><div className="step-marker">{done?<Check size={13}/>:current?<span/>:<i/>}</div><div className="step-content"><div className="step-title">{title}{current&&<em> IN PROGRESS</em>}</div><small>{date}</small></div></div>}
function Field({label,required=false,children}:{label:string;required?:boolean;children:ReactNode}){return <label className="form-field"><span>{label}{required&&<i>Required</i>}</span>{children}</label>}

function AdmissionApplicationForm({notify}:{notify:(message:string)=>void}) {const [scholarship,setScholarship]=useState('No');const [busy,setBusy]=useState(false);const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const data=new FormData(form);setBusy(true);void (async()=>{try{const application=await apiPost<{id:number}>('/applications/',{academic_year:String(data.get('academic_year')||''),entry_year:Number(data.get('entry_year')),department:String(data.get('department')||''),gender:String(data.get('gender')||''),category:String(data.get('category')||''),admission_route:String(data.get('admission_route')||''),has_ebc_ews_certificate:false});const proof=data.get('prn_document');if(proof instanceof File&&proof.size){const upload=new FormData();upload.append('application',String(application.id));upload.append('kind','PRN_PROOF');upload.append('file',proof);const result=await apiUpload<{ocr_status:string;validation_score:number|null;validation_reasons:string[]}>('/documents/',upload);notify(result.ocr_status==='COMPLETED'?`Application saved. PRN proof OCR completed (${result.validation_score??0}% match). Open Documents to upload the rest.`:'Application saved; PRN proof is in staff review. Open Documents to see the OCR status.')}else notify('Application saved. Open Documents to upload PRN proof and other required records.')}catch(error){notify(error instanceof Error?error.message:'Could not save application.')}finally{setBusy(false)}})()};return <form className="panel admission-form" onSubmit={submit}>
  <div className="panel-heading form-intro"><div><h3>Continuing student admission form</h3><p>Complete each section. PRN number and proof are mandatory for all students.</p></div><span className="status-badge">Draft</span></div>
  <fieldset className="form-section"><legend>Admission details</legend><div className="form-grid"><Field label="Academic year" required><select name="academic_year" defaultValue="2026-27"><option value="2026-27">2026–27</option><option value="2027-28">2027–28</option></select></Field><Field label="Admission year" required><select name="entry_year" defaultValue="" required><option value="" disabled>Select year</option><option value="2">2nd year (SE)</option><option value="3">3rd year (TE)</option><option value="4">4th year (BE)</option></select></Field><Field label="Course / degree" required><select defaultValue="" required><option value="" disabled>Select course</option><option>Degree Engineering</option></select></Field><Field label="Branch" required><select name="department" defaultValue="" required><option value="" disabled>Select branch</option>{['Mechanical Engineering','Electronics & Telecommunication Engineering','Electrical Engineering','Computer Engineering','Information Technology','Civil Engineering','Artificial Intelligence & Machine Learning','Mechatronics Engineering'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Admission type / quota" required><select name="admission_route" defaultValue="" required><option value="" disabled>Select type</option><option value="CAP">CAP</option><option value="MANAGEMENT">Management quota</option></select></Field><Field label="Hostel admission" required><select defaultValue="No"><option>Yes</option><option>No</option></select></Field><Field label="Institute roll number"><input name="roll_number"/></Field><Field label="Admission card number"><input name="admission_card_number"/></Field></div></fieldset>
  <fieldset className="form-section"><legend>Student information</legend><div className="form-grid"><Field label="Student full name" required><input name="full_name" required/></Field><Field label="Father’s name" required><input name="father_name" required/></Field><Field label="Mother’s name" required><input name="mother_name" required/></Field><Field label="Date of birth" required><input name="date_of_birth" type="date" required/></Field><Field label="Email address" required><input name="email" type="email" required/></Field><Field label="Phone / mobile number" required><input name="mobile" type="tel" required/></Field><Field label="Gender" required><select name="gender" required defaultValue="F"><option value="F">Female</option><option value="M">Male</option><option value="O">Other</option></select></Field><Field label="Religion"><input name="religion"/></Field><Field label="Caste"><input name="caste"/></Field><Field label="Caste category" required><select name="category" defaultValue="" required><option value="" disabled>Select category</option>{['Open','SC','ST','VJ','DT(A)','SBC','NT(1)','NT(2)','NT(3)','OBC','ESBC'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Eligibility number"><input name="eligibility_number"/></Field><Field label="FE admission year"><input name="fe_admission_year"/></Field><Field label="SE admission year"><input name="se_admission_year"/></Field><Field label="TE admission year"><input name="te_admission_year"/></Field></div></fieldset>
  <fieldset className="form-section prn-section"><legend>PRN · mandatory</legend><p>Staff can use this PRN number to fetch the student’s saved record.</p><div className="form-grid"><Field label="Permanent registration number" required><input name="prn" required autoComplete="off" placeholder="Enter your university PRN"/></Field><Field label="Upload PRN proof" required><input name="prn_document" type="file" accept=".pdf,image/*" required/></Field></div><small>Clear PDF, JPG, or PNG scan of your PRN card or official record.</small></fieldset>
  <fieldset className="form-section"><legend>Scholarship and bank details</legend><div className="form-grid"><Field label="Applied for scholarship?" required><select value={scholarship} onChange={e=>setScholarship(e.target.value)}><option>No</option><option>Yes</option></select></Field>{scholarship==='Yes'&&<><Field label="Scholarship scheme / type" required><input name="scholarship_type" required/></Field><Field label="Bank name"><input name="bank_name"/></Field><Field label="Account holder name"><input name="account_holder"/></Field><Field label="Bank account number"><input name="account_number" inputMode="numeric"/></Field><Field label="IFSC / IRCE code"><input name="bank_code"/></Field><Field label="BSR code"><input name="bsr_code"/></Field><Field label="Scholarship application / approval proof"><input name="scholarship_proof" type="file" accept=".pdf,image/*"/></Field></>}</div>{scholarship==='Yes'&&<p className="form-note">If the scholarship has not been paid to the college, upload its application/status screenshot for staff review.</p>}</fieldset>
  <fieldset className="form-section"><legend>Aadhaar and addresses</legend><div className="form-grid"><Field label="Aadhaar number"><input name="aadhaar" maxLength={12} inputMode="numeric" autoComplete="off" placeholder="12-digit number"/></Field><Field label="Aadhaar document"><input name="aadhaar_document" type="file" accept=".pdf,image/*"/></Field></div><div className="address-columns">{['Permanent','Local'].map(kind=><div className="address-card" key={kind}><h4>{kind} address</h4><Field label="Address" required><textarea name={`${kind.toLowerCase()}_address`} rows={3} required/></Field><div className="form-grid compact-grid"><Field label="District" required><input required/></Field><Field label="State" required><input required/></Field><Field label="PIN code" required><input inputMode="numeric" required/></Field><Field label="Phone / mobile" required><input type="tel" required/></Field></div></div>)}</div></fieldset>
  <div className="form-note fraud-note">Declaration: providing malicious or false information may result in strict action. Students are responsible for educational or financial losses caused by incorrect information.</div><label className="declaration"><input type="checkbox" required/><span>I confirm the information is accurate and may be checked against official records.</span></label><div className="form-grid signature-grid"><Field label="Student signature (type full name)" required><input name="student_signature" required/></Field><Field label="Date" required><input name="signed_date" type="date" required/></Field></div><div className="form-actions"><button type="button" className="outline-button" onClick={()=>notify('Draft saving will be connected to your account backend.')}>Save draft</button><button className="primary-button" disabled={busy}>{busy?'Saving and checking PRN…':'Validate and submit'} <ArrowRight size={15}/></button></div><p className="privacy-note">Identity and bank details should be protected and shown only to authorized staff.</p>
 </form>}

function SectionPage({page,notify}:{page:Page;notify:(message:string)=>void}) {const title:Record<Page,string>={Overview:'Overview','My application':'My application',Documents:'Document centre',Scholarship:'Scholarship','Fees & payment':'Fees & payment','Help & support':'Help & support'};return <><div className="page-title-row"><div><div className="eyebrow green">SVPM · ADMISSIONS 2026–27</div><h1>{title[page]}</h1><p>{page==='My application'?'Review and complete your admission application.':page==='Documents'?'Track document verification.':'Your admissions information.'}</p></div><div className="title-icon"><FileText size={23}/></div></div>{page==='My application'?<AdmissionApplicationForm notify={notify}/>:page==='Documents'?<DocumentChecklist/>:page==='Scholarship'?<ScholarshipCenter/>:page==='Fees & payment'?<FeeCalculator notify={notify}/>:<div className="support-grid"><div className="panel support-card"><span className="soft-icon"><Bot size={20}/></span><h3>Ask the admissions assistant</h3><p>Get help with your application, documents, scholarship, or fees.</p><button className="primary-button" onClick={()=>document.querySelector<HTMLButtonElement>('.chat-launcher')?.click()}>Start a conversation <ArrowRight size={14}/></button></div></div>}<div className="page-footer"><span>© 2026 SVPM College of Engineering</span><span>Admissions 2026–27</span></div></>}

const requiredDocuments:[string,string][]=[['PASSPORT_PHOTO','Passport-size photo'],['AADHAAR','Aadhaar card'],['PRN_PROOF','PRN proof'],['CET_RESULT','CET result'],['MARKSHEET','Previous year / semester marksheet or result'],['FE_ADMISSION_PROOF','FE admission proof / admission form'],['ELIGIBILITY','First-year admission eligibility form'],['SSC_MARKSHEET','10th marksheet'],['HSC_MARKSHEET','12th marksheet'],['LEAVING_CERTIFICATE','12th leaving certificate'],['CASTE','Caste certificate'],['CASTE_VALIDITY','Caste validity certificate'],['NCL','Non-creamy layer certificate (if applicable)'],['INCOME_CERTIFICATE','Income certificate (if applicable)'],['DOMICILE','Domicile certificate'],['RATION_CARD','Ration card'],['SCHOLARSHIP_PROOF','Scholarship application / approval proof']]
type ApplicantApplication={id:number;academic_year:string;entry_year:number;status:string}
type ApplicantDocument={id:number;application:number;kind:string;file:string;ocr_status:string;ocr_confidence:number|null;extracted_fields:Record<string,unknown>;validation_score:number|null;validation_reasons:string[];issue_date:string|null;expiry_date:string|null;review_status:string;uploaded_at:string}
function DocumentChecklist(){const [applications,setApplications]=useState<ApplicantApplication[]>([]);const [documents,setDocuments]=useState<ApplicantDocument[]>([]);const [applicationId,setApplicationId]=useState('');const [kind,setKind]=useState('PRN_PROOF');const [file,setFile]=useState<File|null>(null);const [busy,setBusy]=useState(false);const [notice,setNotice]=useState('Loading your applications and document status…');const load=async()=>{try{const [a,d]=await Promise.all([fetch(`${API_BASE_URL}/applications/`,{credentials:'include'}),fetch(`${API_BASE_URL}/documents/`,{credentials:'include'})]);const aa=await a.json();const dd=await d.json();if(!a.ok)throw new Error(aa.detail||'Could not load applications.');if(!d.ok)throw new Error(dd.detail||'Could not load document status.');setApplications(aa);setDocuments(dd);setApplicationId(current=>current||String(aa[0]?.id||''));setNotice('')}catch(error){setNotice(error instanceof Error?error.message:'Could not reach the admissions backend.')}};useEffect(()=>{void load()},[]);const upload=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!applicationId||!file)return;const form=e.currentTarget;setBusy(true);setNotice('Uploading document and running OCR…');try{const body=new FormData();body.append('application',applicationId);body.append('kind',kind);body.append('file',file);const result=await apiUpload<ApplicantDocument>('/documents/',body);setDocuments(current=>[result,...current.filter(doc=>doc.id!==result.id)]);setFile(null);form.reset();setNotice(result.ocr_status==='COMPLETED'?'OCR finished. Review the match and date results below; uncertain documents are queued for staff.':`Upload saved. OCR status: ${result.ocr_status}. Staff review is required.`)}catch(error){setNotice(error instanceof Error?error.message:'Upload failed.')}finally{setBusy(false)}};const latestFor=(docKind:string)=>documents.find(doc=>doc.kind===docKind&&String(doc.application)===applicationId);return <><section className="panel detail-panel"><div className="panel-heading"><div><h3>Admission document checklist</h3><p>Upload clear scans or PDFs for an existing application. Document requirements may differ by category.</p></div><span className="status-badge">OCR + staff review</span></div>{applications.length>0?<><div className="form-grid"><Field label="Admission application"><select value={applicationId} onChange={e=>setApplicationId(e.target.value)}>{applications.map(app=><option key={app.id} value={app.id}>{app.academic_year} · {app.entry_year}{app.entry_year===2?'nd':app.entry_year===3?'rd':'th'} year · {app.status}</option>)}</select></Field></div><form className="form-grid" onSubmit={upload}><Field label="Document type"><select value={kind} onChange={e=>setKind(e.target.value)}>{requiredDocuments.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></Field><Field label="Choose PDF or image (max 3 MB)"><input type="file" accept=".pdf,.jpg,.jpeg,.png,.tif,.tiff" required onChange={e=>setFile(e.target.files?.[0]||null)}/></Field><div className="form-actions"><button className="primary-button" disabled={busy||!file}>{busy?'Checking document…':'Upload and verify'} <UploadCloud size={14}/></button></div></form></>:<p className="form-note">No admission application found. Complete and submit the admission form first, then return here to upload documents.</p>}{notice&&<div className="lookup-message"><CircleHelp size={16}/>{notice}</div>}<div className="checklist-grid">{requiredDocuments.map(([value,name])=>{const doc=latestFor(value);return <div className="checklist-item" key={value}><span className="file-icon pdf">{value==='PRN_PROOF'?'PRN':'DOC'}</span><div className="doc-copy"><b>{name}</b><small>{doc?`${doc.ocr_status} · ${doc.review_status}${doc.validation_score!==null?` · ${doc.validation_score}% match`:''}`:value==='PRN_PROOF'?'Mandatory · linked to the staff student record':'Waiting for upload'}</small></div><span className={`document-status ${doc?.review_status==='VERIFIED'?'green':'amber'}`}>{doc?.review_status||'Pending'}</span></div>})}</div><div className="ai-note"><Sparkles size={17}/><div><b>OCR matching and validity checks</b><p>OCR extracts readable text, compares the student name with the staff record, and checks income-certificate issue year and NCL expiry when those dates can be read. Uncertain matches or dates go to staff review; OCR alone does not prove a document is genuine.</p></div></div></section>{documents.filter(doc=>String(doc.application)===applicationId).map(doc=><section className="panel detail-panel" key={doc.id}><div className="panel-heading"><div><h3>{requiredDocuments.find(([value])=>value===doc.kind)?.[1]||doc.kind}</h3><p>Uploaded {new Date(doc.uploaded_at).toLocaleString()}</p></div><span className="status-badge">{doc.review_status}</span></div><p>OCR: {doc.ocr_status}{doc.ocr_confidence!==null?` · text confidence ${doc.ocr_confidence}%`:''}{doc.validation_score!==null?` · match score ${doc.validation_score}%`:''}</p>{doc.issue_date&&<p>Issue date detected: {doc.issue_date}</p>}{doc.expiry_date&&<p>Expiry date detected: {doc.expiry_date}</p>}{doc.validation_reasons.length>0&&<ul>{doc.validation_reasons.map((reason,index)=><li key={index}>{reason}</li>)}</ul>}</section>)}</>}
function ScholarshipCenter(){const [applied,setApplied]=useState('Yes');const [status,setStatus]=useState('Applied — awaiting decision');return <><section className="panel detail-panel scholarship-panel"><span className="scholar-icon"><GraduationCap size={24}/></span><div className="scholarship-content"><span className="status-badge">Evidence required when applied</span><h3>MahaDBT scholarship status</h3><p>Keep scholarship documents separate from the admission document checklist. If funds have not reached the college, provide application or approval evidence for staff review.</p><div className="form-grid scholarship-fields"><Field label="Applied for scholarship?"><select value={applied} onChange={e=>setApplied(e.target.value)}><option>Yes</option><option>No</option></select></Field>{applied==='Yes'&&<><Field label="Current status"><select value={status} onChange={e=>setStatus(e.target.value)}><option>Applied — awaiting decision</option><option>Approved — funds not credited</option><option>Funds credited to college</option><option>Rejected</option></select></Field><Field label="Scholarship application / approval screenshot" required><input type="file" accept="image/*,.pdf" required/></Field><Field label="Scholarship award amount (₹)"><input type="number" min="0" placeholder="Enter amount shown on approval"/></Field></>}</div>{applied==='Yes'&&<div className="form-note fraud-note">False or altered information may lead to strict action. Students are responsible for losses caused by incorrect information.</div>}<div className="form-actions"><button className="primary-button" onClick={()=>window.alert('Scholarship proof selected for review. Backend upload is not connected yet.')}>Submit scholarship evidence <ArrowRight size={14}/></button></div></div></section><section className="panel detail-panel"><div className="panel-heading"><div><h3>Scholarship review stages</h3><p>Funding is counted only according to the college’s confirmed policy.</p></div></div><div className="review-track"><span/><span/><span/></div><div className="review-labels"><small>Application proof</small><small>Staff review</small><small>College credit confirmed</small></div></section></>}
function FeeCalculator({notify}:{notify:(message:string)=>void}) {
  const [category,setCategory]=useState('Open')
  const [gender,setGender]=useState('Female')
  const [cap,setCap]=useState('CAP round')
  const [ebcEws,setEbcEws]=useState(false)
  const [arrears,setArrears]=useState(0)
  const [shareholder,setShareholder]=useState(false)
  const isSc=category==='SC'
  const isCategoryConcession=['ST','NT(1)','NT(2)','NT(3)','VJ','DT(A)','TFWS'].includes(category)
  const isOBCGroup=['OBC','SBC','EWS','EBC'].includes(category)
  const feeBeforeGender=isSc?350:isCategoryConcession?10867:isOBCGroup?50109:category==='Open'&&ebcEws?50109:89350
  const feeNeedsConfirmation=category==='SEBC'&&gender!=='Female'
  const annual=gender==='Female'&&!isSc?10867:feeBeforeGender
  const due=feeNeedsConfirmation?null:annual+arrears
  const feeReason=feeNeedsConfirmation?'Fee group not specified in supplied circular':gender==='Female'&&!isSc?'Girls lump-sum fee':isSc?'₹350 fee category':category==='Open'&&ebcEws?'Open with EBC/EWS certificate · OBC net rate':isOBCGroup?'Category fee after scholarship deduction':'Full fee'
  return <>
    <section className="panel detail-panel">
      <div className="panel-heading"><div><h3>Fee estimate</h3><p>Using only the latest fee column supplied (2025–26), with the rules you just specified.</p></div><span className="status-badge">Latest supplied rates</span></div>
      <div className="form-grid fee-inputs">
        <Field label="Student category"><select value={category} onChange={e=>{setCategory(e.target.value);setEbcEws(false)}}>{['Open','SC','ST','NT(1)','NT(2)','NT(3)','VJ','DT(A)','TFWS','OBC','SBC','EWS','EBC','SEBC'].map(c=><option key={c}>{c}</option>)}</select></Field>
        <Field label="Gender"><select value={gender} onChange={e=>setGender(e.target.value)}><option>Female</option><option>Male</option><option>Other</option></select></Field>
        <Field label="Admission route"><select value={cap} onChange={e=>setCap(e.target.value)}><option>CAP round</option><option>Other / management</option></select></Field>
        {category==='Open'&&<label className="declaration fee-check"><input type="checkbox" checked={ebcEws} onChange={e=>setEbcEws(e.target.checked)}/><span>Valid EBC/EWS certificate</span></label>}
        <Field label="Previous unpaid balance (₹)"><input type="number" min="0" value={arrears} onChange={e=>setArrears(Number(e.target.value))}/></Field>
      </div>
      <div className="fee-breakdown"><div><span>{feeReason}</span><b>{feeNeedsConfirmation?'Awaiting staff':`₹${annual.toLocaleString('en-IN')}`}</b></div><div><span>Previous unpaid balance carried forward</span><b>+ ₹{arrears.toLocaleString('en-IN')}</b></div><div className="fee-total"><span>Estimated amount due</span><b>{due===null?'Awaiting staff confirmation':`₹${due.toLocaleString('en-IN')}`}</b></div></div>
      {feeNeedsConfirmation&&<p className="form-note">SEBC is not listed as a separate group in the supplied fee circular. Staff must confirm the applicable fee before payment.</p>}
      {cap==='CAP round'&&<div className="ai-note"><GraduationCap size={17}/><div><b>MahaDBT scholarship</b><p>CAP-round applicants should apply for the applicable MahaDBT scholarship and provide application/approval proof in the separate Scholarship section. Listed category fees are treated as net payable amounts; this calculator does not subtract a second scholarship amount.</p></div></div>}
      <p className="privacy-note">Girls pay ₹10,867 lump sum regardless of category, except the ₹350 category. Open-category students pay full fees unless they have a valid EBC/EWS certificate. The ₹50,109 OBC/EBC/EWS rate is already after scholarship deduction.</p>
      <div className="form-actions"><button className="primary-button" disabled={feeNeedsConfirmation} onClick={()=>notify('Razorpay will be connected after backend setup')}>Continue to Razorpay <ArrowRight size={14}/></button></div>
    </section>
    <section className="panel detail-panel shareholder-panel">
      <div className="panel-heading"><div><h3>Shareholder / Sabhasad family payment</h3><p>For students whose parent or guardian is a shareholder of Shivnagar Sugar Cane Factory, Malegaon Baramati.</p></div><span className="status-badge">Manual staff process</span></div>
      <label className="declaration"><input type="checkbox" checked={shareholder} onChange={e=>setShareholder(e.target.checked)}/><span>Student is applying under the factory shareholder / Sabhasad process.</span></label>
      {shareholder&&<><div className="form-grid"><Field label="Shareholder name" required><input required placeholder="Parent / guardian name"/></Field><Field label="Shareholder / member number" required><input required/></Field><Field label="Relationship to student" required><input required placeholder="e.g. Parent"/></Field><Field label="Factory affidavit" required><input required type="file" accept=".pdf,image/*"/></Field><Field label="Sugarcane bill / supporting proof" required><input required type="file" accept=".pdf,image/*"/></Field><Field label="Additional note for admissions office"><textarea rows={2}/></Field></div><div className="manual-review-note"><ShieldCheck size={16}/><span>Admin staff manually verify the affidavit and supporting records, coordinate the fee against the sugarcane bill, and update payment status. No automatic deduction or approval occurs online.</span></div><div className="form-actions"><button className="outline-button" onClick={()=>notify('Shareholder claim submitted for manual staff review after backend setup.')}>Submit for staff review <ArrowRight size={14}/></button></div></>}
    </section>
  </>
}
function PRNLookup(){const [prn,setPrn]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [record,setRecord]=useState<Record<string,unknown>|null>(null);const lookup=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setError('');setRecord(null);try{const r=await fetch(`/api/staff/students/lookup/?prn=${encodeURIComponent(prn.trim())}`,{credentials:'include'});if(!r.ok)throw new Error(r.status===404?'No record found for that PRN.':'The student records API is not available yet.');if(!(r.headers.get('content-type')||'').includes('application/json'))throw new Error('The student records API is not available yet.');const data=await r.json() as Record<string,unknown>;setRecord((data.student&&typeof data.student==='object'?data.student:data) as Record<string,unknown>)}catch(err){setError(err instanceof Error?err.message:'Could not fetch this student record.')}finally{setBusy(false)}};return <section className="panel prn-lookup"><div className="panel-heading"><div><h3>Fetch student by PRN</h3><p>Staff only · Enter the exact PRN to retrieve the saved record.</p></div><span className="soft-icon"><Search size={17}/></span></div><form className="prn-search-form" onSubmit={lookup}><input value={prn} onChange={e=>setPrn(e.target.value)} required placeholder="Enter student PRN" aria-label="Student PRN"/><button className="primary-button" disabled={busy}>{busy?'Searching…':'Fetch record'} <ArrowRight size={14}/></button></form>{error&&<div className="lookup-message error-message"><CircleHelp size={16}/>{error} Sign in to the Django API to retrieve student records.</div>}{record&&<div className="lookup-record"><div className="lookup-record-title"><ShieldCheck size={16}/><b>Student record loaded</b><span>{prn}</span></div><div className="lookup-record-grid">{Object.entries(record).filter(([k])=>!['password','password_hash'].includes(k.toLowerCase())).map(([k,v])=><div key={k}><small>{k.replace(/_/g,' ')}</small><b>{/aadhaar|account.?number/i.test(k)?'•••• •••• '+String(v).slice(-4):typeof v==='object'?JSON.stringify(v):String(v??'—')}</b></div>)}</div><p>Aadhaar and bank numbers are masked in this view.</p></div>}</section>}

type StudentRecordRow={id:number;prn:string;full_name:string;email:string;mobile:string;department:string;year_level:'FE'|'SE'|'TE'|'BE';first_year_admission:string}
const departments=['Computer Engineering','Information Technology','Electronics & Telecommunication Engineering','Electrical Engineering','Civil Engineering','Mechanical Engineering','Mechatronics Engineering','Artificial Intelligence & Machine Learning']
const staffDocumentTypes:[string,string][]=[...requiredDocuments,['OTHER','Other supporting document']]
function StaffStudentRecords(){
  const [year,setYear]=useState<'FE'|'SE'|'TE'|'BE'>('FE')
  const [department,setDepartment]=useState('')
  const [search,setSearch]=useState('')
  const [records,setRecords]=useState<StudentRecordRow[]>([])
  const [loading,setLoading]=useState(false)
  const [error,setError]=useState('')
  const [notice,setNotice]=useState('')
  const [editing,setEditing]=useState<number|null>(null)
  const [form,setForm]=useState({prn:'',full_name:'',email:'',mobile:'',department:departments[0],year_level:'FE' as StudentRecordRow['year_level'],first_year_admission:''})
  const refresh=async()=>{setLoading(true);setError('');try{const params=new URLSearchParams({year_level:year,limit:'200'});if(department)params.set('department',department);if(search.trim())params.set('search',search.trim());const response=await fetch(`${API_BASE_URL}/staff/students/?${params}`,{credentials:'include'});const data=await response.json().catch(()=>({detail:'Could not read student records.'}));if(!response.ok)throw new Error(data.detail||'Could not load student records. Sign in with a staff account.');setRecords(Array.isArray(data.results)?data.results:[])}catch(err){setError(err instanceof Error?err.message:'Could not load records.')}finally{setLoading(false)}}
  useEffect(()=>{const timer=window.setTimeout(()=>{void refresh()},250);return()=>window.clearTimeout(timer)},[year,department,search])
  const reset=()=>{setEditing(null);setForm({prn:'',full_name:'',email:'',mobile:'',department:department||departments[0],year_level:year,first_year_admission:''})}
  const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');setNotice('');try{if(editing){await apiPatch(`/staff/students/${editing}/`,form);setNotice('Student record updated.')}else{await apiPost('/staff/students/',form);setNotice('Student record added.')}reset();await refresh()}catch(err){setError(err instanceof Error?err.message:'Could not save this record.')}}
  const startEdit=(row:StudentRecordRow)=>{setEditing(row.id);setForm({prn:row.prn,full_name:row.full_name,email:row.email,mobile:row.mobile,department:row.department,year_level:row.year_level,first_year_admission:row.first_year_admission||''})}
  const importCsv=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');setNotice('');const importForm=e.currentTarget;const input=importForm.elements.namedItem('student_csv') as HTMLInputElement;const file=input.files?.[0];if(!file)return;const body=new FormData();body.append('file',file);try{const result=await apiUpload<{created:number;updated:number;failed:number;errors:{row:number;prn:string;errors:unknown}[]}>('/staff/students/import/',body);setNotice(`Import complete · ${result.created} added, ${result.updated} updated, ${result.failed} failed.`);setError(result.errors?.length?`Rows with issues: ${result.errors.slice(0,5).map(x=>`${x.row} (${x.prn||'blank PRN'})`).join(', ')}${result.errors.length>5?'…':''}`:'');importForm.reset();await refresh()}catch(err){setError(err instanceof Error?err.message:'Could not import CSV.')}}
  return <section className="panel office-use student-records-panel"><div className="panel-heading"><div><h3>Student records · year and department</h3><p>Browse, add, edit, and import staff-managed student records for each year and department.</p></div><span className="staff-role-badge"><LockKeyhole size={13}/> Staff only</span></div>
    <div className="record-year-tabs" role="tablist" aria-label="Student year">{(['FE','SE','TE','BE'] as const).map(item=><button type="button" role="tab" aria-selected={year===item} className={year===item?'active':''} key={item} onClick={()=>{setYear(item);if(editing!==null)reset()}}>{item}<small>{item==='FE'?'First year':item==='SE'?'Second year':item==='TE'?'Third year':'Fourth year'}</small></button>)}</div>
    <form className="record-import-row" onSubmit={importCsv}><div><b>Upload a student list</b><small>CSV columns: prn, full_name, email, mobile, department, year_level, first_year_admission · max 3 MB</small></div><input type="file" name="student_csv" accept=".csv,text/csv" required/><button className="outline-button"><UploadCloud size={14}/> Import CSV</button></form>
    <form className="record-edit-form" onSubmit={save}><div className="panel-heading record-form-heading"><div><h4>{editing?'Edit student record':'Add student record'}</h4><p>Student record is the source used for PRN-based registration matching.</p></div>{editing!==null&&<button type="button" className="outline-button compact" onClick={reset}>Cancel edit</button>}</div><div className="form-grid"><Field label="PRN" required><input value={form.prn} onChange={e=>setForm({...form,prn:e.target.value})} required/></Field><Field label="Student full name" required><input value={form.full_name} onChange={e=>setForm({...form,full_name:e.target.value})} required/></Field><Field label="Email" required><input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} required/></Field><Field label="Mobile number" required><input type="tel" value={form.mobile} onChange={e=>setForm({...form,mobile:e.target.value})} required/></Field><Field label="Department" required><select value={form.department} onChange={e=>setForm({...form,department:e.target.value})}>{departments.map(item=><option key={item}>{item}</option>)}</select></Field><Field label="Year level" required><select value={form.year_level} onChange={e=>setForm({...form,year_level:e.target.value as StudentRecordRow['year_level']})}>{(['FE','SE','TE','BE'] as const).map(item=><option key={item} value={item}>{item}</option>)}</select></Field><Field label="First-year admission academic year"><input placeholder="e.g. 2023-24" value={form.first_year_admission} onChange={e=>setForm({...form,first_year_admission:e.target.value})}/></Field></div><div className="form-actions"><button className="primary-button">{editing?'Save changes':'Add student record'} <Check size={14}/></button></div></form>
    {error&&<div className="lookup-message error-message"><CircleHelp size={16}/>{error}</div>}{notice&&<div className="lookup-message"><Check size={16}/>{notice}</div>}
    <div className="record-list-toolbar"><div><b>{year} student directory</b><small>{loading?'Loading…':`${records.length} record${records.length===1?'':'s'} shown`}</small></div><Field label="Department"><select value={department} onChange={e=>setDepartment(e.target.value)}><option value="">All departments</option>{departments.map(item=><option key={item}>{item}</option>)}</select></Field><label className="record-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search PRN, name, email, mobile"/></label><button type="button" className="outline-button compact" onClick={()=>void refresh()}>Refresh</button></div>
    <div className="table-wrap"><table><thead><tr><th>PRN</th><th>STUDENT</th><th>DEPARTMENT</th><th>YEAR</th><th>EMAIL / MOBILE</th><th></th></tr></thead><tbody>{records.map(row=><tr key={row.id}><td><b>{row.prn}</b></td><td>{row.full_name}</td><td>{row.department}</td><td><span className="table-status">{row.year_level}</span></td><td>{row.email}<br/><small>{row.mobile}</small></td><td><button type="button" className="outline-button compact" onClick={()=>startEdit(row)}>Edit</button></td></tr>)}{!loading&&!records.length&&<tr><td colSpan={6} className="record-empty">No {year} records match these filters.</td></tr>}</tbody></table></div>
  </section>
}

type StaffDocumentRow={id:number;prn:string;student_name:string;year_level:string;department:string;kind:string;file_name:string;review_status:string;ocr_status:string;validation_score:number|null;issue_date:string|null;expiry_date:string|null;validation_reasons:string[];extracted_fields:Record<string,unknown>;is_staff_reference:boolean;uploaded_at:string}
function StaffDocumentsPanel(){
  const [prn,setPrn]=useState('')
  const [student,setStudent]=useState<{prn:string;full_name:string;year_level:string;department:string}|null>(null)
  const [documents,setDocuments]=useState<StaffDocumentRow[]>([])
  const [kind,setKind]=useState(staffDocumentTypes[0][0])
  const [file,setFile]=useState<File|null>(null)
  const [busy,setBusy]=useState(false)
  const [error,setError]=useState('')
  const [notice,setNotice]=useState('')
  const load=async(event?:FormEvent)=>{event?.preventDefault();setError('');setNotice('');setStudent(null);setDocuments([]);if(!prn.trim()){setError('Enter a student PRN first.');return}setBusy(true);try{const response=await fetch(`${API_BASE_URL}/staff/student-documents/?prn=${encodeURIComponent(prn.trim())}`,{credentials:'include'});const data=await response.json().catch(()=>({detail:'Could not read student documents.'}));if(!response.ok)throw new Error(data.detail||'Could not load this student.');setStudent(data.student);setDocuments(Array.isArray(data.documents)?data.documents:[])}catch(err){setError(err instanceof Error?err.message:'Could not load student documents.')}finally{setBusy(false)}}
  const upload=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();setError('');setNotice('');if(!student){setError('Load a student by PRN before uploading.');return}if(!file)return;if(file.size>3*1024*1024){setError('Each document must be 3 MB or smaller.');return}const uploadForm=event.currentTarget;setBusy(true);try{const body=new FormData();body.append('prn',student.prn);body.append('kind',kind);body.append('file',file);const row=await apiUpload<StaffDocumentRow>('/staff/student-documents/',body);setDocuments(current=>[row,...current]);setFile(null);uploadForm.reset();setNotice(`${staffDocumentTypes.find(([value])=>value===row.kind)?.[1]||row.kind} uploaded. OCR status: ${row.ocr_status}.`)}catch(err){setError(err instanceof Error?err.message:'Could not upload this document.')}finally{setBusy(false)}}
  const verifyReference=async(doc:StaffDocumentRow)=>{setError('');try{await apiPatch(`/staff/documents/${doc.id}/`,{review_status:'VERIFIED',staff_note:'Staff verified as the reference copy for this exact document type.'});setDocuments(current=>current.map(item=>item.id===doc.id?{...item,review_status:'VERIFIED'}:item));setNotice(`${staffDocumentTypes.find(([value])=>value===doc.kind)?.[1]||doc.kind} marked as the verified reference copy.`)}catch(err){setError(err instanceof Error?err.message:'Could not verify the reference copy.')}}
  return <section id="staff-student-documents" className="panel office-use staff-documents-panel"><div className="panel-heading"><div><h3>Student documents · staff upload</h3><p>Upload and review a student’s records by PRN. Student submissions compare with a staff-verified file of the exact same type, such as caste certificate against caste certificate. Max 3 MB per file.</p></div><span className="staff-role-badge"><LockKeyhole size={13}/> Staff only</span></div>
    <form className="staff-doc-lookup" onSubmit={load}><Field label="Student PRN"><input value={prn} onChange={e=>setPrn(e.target.value)} placeholder="Enter the student PRN" required/></Field><button className="primary-button" disabled={busy}>{busy?'Loading…':'Load student documents'} <Search size={14}/></button></form>
    {student&&<><div className="staff-doc-student"><div><small>SELECTED STUDENT</small><b>{student.full_name}</b></div><span>{student.prn}</span><span>{student.year_level} · {student.department}</span></div>
      <form className="staff-doc-upload" onSubmit={upload}><Field label="Document to upload"><select value={kind} onChange={e=>setKind(e.target.value)}>{staffDocumentTypes.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></Field><Field label="Select PDF or image (max 3 MB)"><input type="file" accept=".pdf,.jpg,.jpeg,.png,.tif,.tiff" required onChange={e=>setFile(e.target.files?.[0]||null)}/></Field><button className="primary-button" disabled={busy||!file}>{busy?'Uploading…':'Upload document'} <UploadCloud size={14}/></button></form>
      <div className="panel-heading staff-doc-table-heading"><div><h4>Document checklist</h4><p>Uploaded files appear with OCR and staff-review status.</p></div><span className="status-badge">{documents.length} uploaded</span></div>
      <div className="table-wrap"><table><thead><tr><th>DOCUMENT TYPE</th><th>UPLOADED FILE</th><th>OCR / MATCH</th><th>REVIEW STATUS</th><th>DATES EXTRACTED</th><th>ACTION</th></tr></thead><tbody>{staffDocumentTypes.map(([docKind,label])=>{const docs=documents.filter(doc=>doc.kind===docKind);return docs.length?docs.map(doc=><tr key={doc.id}><td><b>{label}</b></td><td>{doc.file_name}</td><td>{doc.ocr_status}{doc.validation_score!==null?` · ${doc.validation_score}%`:''}{doc.extracted_fields?.reference_match===true?' · same-type reference matched':doc.extracted_fields?.reference_match===false?' · reference mismatch':''}</td><td><span className={`table-status ${doc.review_status==='VERIFIED'?'':'flagged'}`}>{doc.review_status}</span></td><td>{doc.issue_date||'—'}{doc.expiry_date?` · expires ${doc.expiry_date}`:''}</td><td className="staff-doc-actions"><a className="outline-button compact" href={`${API_BASE_URL}/staff/documents/${doc.id}/download/`} target="_blank" rel="noreferrer">Download <ArrowDown size={12}/></a>{doc.is_staff_reference&&doc.review_status!=='VERIFIED'&&<button type="button" className="outline-button compact" onClick={()=>void verifyReference(doc)}>Verify reference</button>}</td></tr>):<tr key={docKind}><td><b>{label}</b></td><td colSpan={5} className="record-empty">Not uploaded</td></tr>})}</tbody></table></div>
    </>}{error&&<div className="lookup-message error-message"><CircleHelp size={16}/>{error}</div>}{notice&&<div className="lookup-message"><Check size={16}/>{notice}</div>}
  </section>
}

function StaffIntakeAndVerification({notify}:{notify:(message:string)=>void}){const [score,setScore]=useState(87);const [result,setResult]=useState('Awaiting comparison');const [department,setDepartment]=useState('Computer Engineering');const [year,setYear]=useState('1st year');const [keys,setKeys]=useState({prn:'',email:'',mobile:'',aadhaar:''});const [checked,setChecked]=useState(false);const route=score>=90?'Auto-check passed · continue workflow':'Manual verification required';return <><section className="panel office-use"><div className="panel-heading"><div><h3>Import existing student records</h3><p>Store baseline first-year files by department and year so later applications can compare against them.</p></div><span className="staff-role-badge"><LockKeyhole size={13}/> Staff only</span></div><div className="form-grid"><Field label="Department"><select value={department} onChange={e=>setDepartment(e.target.value)}>{['Computer Engineering','Information Technology','Electronics & Telecommunication','Electrical Engineering','Civil Engineering','Mechanical Engineering','Mechatronics','Artificial Intelligence'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Record year"><select value={year} onChange={e=>setYear(e.target.value)}>{['1st year','2nd year','3rd year','4th year'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Student records / documents (multiple)" required><input type="file" accept=".csv,.xlsx,.pdf,image/*" multiple required/></Field></div><p className="privacy-note">Files are grouped under {department} / {year}. Upload and storage require the staff-protected backend.</p><div className="form-actions"><button className="primary-button" onClick={()=>notify('Record import selected. Connect the protected storage API to save it.')}>Import records <UploadCloud size={14}/></button></div></section><section className="panel office-use"><div className="panel-heading"><div><h3>Duplicate identity check</h3><p>PRN, email, mobile, and Aadhaar should each identify one student account.</p></div><span className="soft-icon"><ShieldCheck size={17}/></span></div><div className="form-grid">{(['prn','email','mobile','aadhaar'] as const).map(key=><Field key={key} label={key==='prn'?'PRN':key[0].toUpperCase()+key.slice(1)}><input value={keys[key]} onChange={e=>setKeys({...keys,[key]:e.target.value})} placeholder={`Enter ${key}`}/></Field>)}</div><div className="form-actions"><button className="outline-button" onClick={()=>setChecked(true)}>Check duplicates <Search size={14}/></button></div>{checked&&<div className="lookup-message"><CircleHelp size={16}/>The uniqueness check needs the student database API. Do not create another account until the server confirms all four identifiers.</div>}</section><section className="panel office-use"><div className="panel-heading"><div><h3>AI comparison routing</h3><p>Threshold: 90%. Under 90% is sent to the manual verification queue.</p></div><span className="soft-icon"><Sparkles size={17}/></span></div><label className="score-control"><span>Demo match score <b>{score}%</b></span><input type="range" min="0" max="100" value={score} onChange={e=>setScore(Number(e.target.value))}/></label><div className={`route-result ${score>=90?'route-pass':'route-review'}`}><ShieldCheck size={17}/><b>{route}</b></div><p className="form-note">This control demonstrates routing only. It does not analyze uploaded files or issue admission approval. A real AI document service and hard checks must be integrated and validated on the backend.</p><div className="form-actions"><button className="primary-button" onClick={()=>setResult(route)}>Simulate document comparison <ArrowRight size={14}/></button></div>{result!=='Awaiting comparison'&&<div className="lookup-message">Demo result: {result}. Actual decisions must come from the verification service.</div>}</section></>}

function OfficeUseForm({notify}:{notify:(message:string)=>void}){return <form className="panel office-use" onSubmit={e=>{e.preventDefault();notify('Office-use details validated. Connect the backend to save them.')}}><div className="panel-heading"><div><h3>Office use only</h3><p>Complete after staff confirms the student record and fee payment.</p></div><span className="staff-role-badge"><LockKeyhole size={13}/> Staff only</span></div><div className="form-grid"><Field label="Amount received (₹)"><input name="office_amount" type="number" min="0"/></Field><Field label="Demand draft number"><input name="demand_draft_number"/></Field><Field label="Paid-via receipt number"><input name="receipt_number"/></Field><Field label="Payment date"><input name="payment_date" type="date"/></Field><Field label="Cashier signature / staff name"><input name="cashier_signature"/></Field></div><div className="form-actions"><button className="primary-button">Save office record <Check size={14}/></button></div></form>}

function StaffShareholderReview({notify}:{notify:(message:string)=>void}){const [status,setStatus]=useState('Pending manual review');const [note,setNote]=useState('');return <section className="panel office-use"><div className="panel-heading"><div><h3>Shareholder / Sabhasad claims</h3><p>Admin staff verify submitted affidavits and sugarcane bills manually.</p></div><span className="staff-role-badge"><LockKeyhole size={13}/> Staff only</span></div><div className="shareholder-review-card"><div><b>Claim review workflow</b><small>Open each student’s uploaded affidavit and supporting bill; confirm the fee adjustment with the college office.</small></div><Field label="Review status"><select value={status} onChange={e=>setStatus(e.target.value)}><option>Pending manual review</option><option>Documents verified · office processing</option><option>More documents required</option><option>Not eligible</option><option>Fee settled through sugarcane bill</option></select></Field><Field label="Staff review note"><textarea value={note} onChange={e=>setNote(e.target.value)} rows={2} placeholder="Record what was checked and next action"/></Field><div className="manual-review-note"><ShieldCheck size={16}/><span>Do not mark payment complete until the responsible office confirms the sugarcane-bill settlement.</span></div><div className="form-actions"><button className="primary-button" onClick={()=>notify(`Demo status: ${status}. Staff notes and changes require the backend to persist.`)}>Save manual review <Check size={14}/></button></div></div></section>}

function StaffDashboard({notify}:{notify:(message:string)=>void}){return <><div className="page-title-row"><div><div className="eyebrow green">STAFF WORKSPACE · 2026–27</div><h1>Admissions overview</h1><p>Review student records and document status.</p></div><button className="outline-button" onClick={()=>notify('Report export will connect to the backend')}><ArrowDown size={15}/> Export report</button></div><PRNLookup/><StaffDocumentsPanel/><StaffStudentRecords/><StaffIntakeAndVerification notify={notify}/><StaffShareholderReview notify={notify}/><OfficeUseForm notify={notify}/><div className="staff-stats"><div className="panel staff-stat"><span>Total applications</span><b>1,284</b><small>Sample dashboard data</small></div><div className="panel staff-stat"><span>Awaiting review</span><b>86</b><small className="orange-text">Requires attention</small></div><div className="panel staff-stat"><span>Documents flagged</span><b>24</b><small>Across 18 applications</small></div><div className="panel staff-stat"><span>Fees collected</span><b>₹42.8L</b><small>Sample dashboard data</small></div></div><div className="panel queue-panel"><div className="panel-heading"><div><h3>Applications needing review</h3><p>AI match below 90%, missing records, and exception cases belong here.</p></div><button className="outline-button compact" onClick={()=>notify('Review filters will be connected to the backend')}>Filter <ChevronDown size={14}/></button></div><div className="table-wrap"><table><thead><tr><th>APPLICANT</th><th>APPLICATION ID</th><th>COURSE</th><th>MATCH</th><th>STATUS</th></tr></thead><tbody>{[['Aditi Sharma','SVPM-DEMO-10482','Computer Engineering','87%','Manual verification'],['Rohan Deshmukh','SVPM-DEMO-10477','Mechanical Engineering','94%','Auto-check passed'],['Sneha Patil','SVPM-DEMO-10469','Information Technology','Needs review','Scholarship review']].map(([n,id,c,score,s])=><tr key={id}><td><span className="table-avatar">{n.split(' ').map(x=>x[0]).join('')}</span><b>{n}</b></td><td>{id}</td><td>{c}</td><td>{score}</td><td><span className={`table-status ${score==='87%'||score==='Needs review'?'flagged':''}`}>{s}</span></td></tr>)}</tbody></table></div></div></>}

export default App
